SELECT t0.ACCT_NAME AS "Name" FROM ref_data.account_master AS t0 LEFT OUTER JOIN (SELECT DISTINCT t2.ACCOUNT_ID AS "ACCOUNT_ID" FROM trading.contractualposition AS t2 WHERE t2.in_z <= '2024-09-01 12:00:00' AND (t2.out_z > '2024-09-01 12:00:00' OR t2.out_z IS NULL)) AS t1 ON (t0.ID = t1.ACCOUNT_ID) WHERE t1.ACCOUNT_ID IS NOT NULL AND t0.in_z <= '2024-09-01 12:00:00' AND (t0.out_z > '2024-09-01 12:00:00' OR t0.out_z IS NULL)
